INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(303, 'plPL', 'Wojna z Czarnorytymi', 'Wojna szaleje i w kraju, i za granicą. Podczas gdy dzielni krasnoludzcy żołnierze oddają życie na dalekich ziemiach w imię Przymierza, nasze własne ziemie padają ofiarą niegodziwości Czarnorytych. Zrównali z ziemią Most Thandol. Wkrótce potem padło Dun Modr.$b$bMusisz zebrać siły i zepchnąć front. Jeśli zabijesz 10 krasnoludów Czarnorytych, 5 tunelarzy, 5 sabotażystów i 5 minierów, rezerwa może zdążyć dokończyć natarcie.$b$bA teraz pośpiesz się!', 'Motley Garmason w Dun Modr chce, żebyś $gzabił:zabiła; 10 krasnoludów Czarnorytych, 5 tunelarzy Czarnorytych, 5 sabotażystów Czarnorytych i 5 minierów Czarnorytych.', '', 'Wróć do Motleya Garmasona w Dun Modr na Bagniskach.', '', '', '', '', 0),
(377, 'plPL', 'Zbrodnia i kara', 'Jakby mało było zaniedbywania mieszkańców Kniei Zmierzchu, teraz Izba Szlachty pluje w twarz Radzie Mrocznych Włości, postanawiając uwięzić Dextrena Warda w Wichrogrodzie, zamiast ściąć łotra zgodnie z wyrokiem lorda Ebonlocke\'a.$b$bWard został przyłapany na sprzedawaniu ciał z cmentarza Morbentowi Felowi, a za taką zbrodnię grozi kara śmierci. Mimo to Wichrogród uznaje Warda za swojego więźnia.$b$bZgładź Warda w Kazamatach – przynieś mi jego rękę – a cię wynagrodzę.', 'Rajca Millstipe z Mrocznych Włości chce, żebyś $gprzyniósł:przyniosła; mu rękę Dextrena Warda.', '', 'Wróć do rajcy Millstipe\'a w Mrocznych Włościach w Kniei Zmierzchu.', '', '', '', '', 0),
(378, 'plPL', 'Gniew sięga głęboko', '$GDowiodłeś:Dowiodłaś; swojej lojalności wobec króla Magniego, $N. A twoja nienawiść do czarnoryckiej hołoty jest równie wielka jak moja.$b$bJest zadanie, które chciałbym wykonać sam, ale honor nakazuje mi zostać przy Długowarkoczu. Roggo zebrał jednak informacje, które dowodzą, że Kam Głębogniew brał udział w spisku, który doprowadził do ataku na Most Thandol. To przez plany Głębogniewa Długowarkocz stracił swoich bliskich.$b$bGłębogniew jest przetrzymywany z powodów politycznych w Kazamatach. Chcę jego śmierci, $N. Za Długowarkocza! Przynieś mi jego głowę!', 'Motley Garmason chce, żebyś $gprzyniósł:przyniosła; mu do Dun Modr głowę Kama Głębogniewa.', '', 'Wróć do Motleya Garmasona w Dun Modr na Bagniskach.', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(377, 'plPL', 'A więc Dextren Ward w końcu zapłacił za swoje zbrodnie przeciw ludzkości? Mówię: dobrze, że świat pozbył się tej szumowiny. I twoje zdrowie, $gprzyjacielu:przyjaciółko;! Nie tylko $gdałeś:dałaś; rodzinom zmarłych spokój, na który zasługują, ale też $gwysłałeś:wysłałaś; dobitną wiadomość tym skorumpowanym urzędasom z Izby Szlachty. Wichrogród musi sprostać potrzebom mieszkańców Kniei Zmierzchu, albo wyzwolimy się spod jego tyranii.', 0),
(378, 'plPL', 'A więc Kam Głębogniew w końcu poczuł, jak to jest znaleźć się w uścisku śmierci? Dobrze. Należało się tej tchórzliwej czarnoryckiej szumowinie. Dobrze się $gspisałeś:spisałaś;, $N. Ofiary ataku na Most Thandol były tylko ofiarami w świecie rozdartym wojną i niepokojami. Ich rodziny zaznają spokoju, wiedząc, że Głębogniew poniósł zasłużoną karę. Śmierć brata Długowarkocza została pomszczona.', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(377, 'plPL', 'Dopóki ktoś, kto bezcześci zmarłych, jak Dextren Ward, może żyć, sprawiedliwość jest zdradzona. Wróć do mnie, gdy wyrok śmierci lorda Ebonlocke\'a zostanie wykonany na tym plugawcy, Wardzie. Pozwolimy rodzinom zmarłych zamknąć ten rozdział, a co więcej, wyślemy wyraźną wiadomość Izbie Szlachty w Wichrogrodzie.', 0),
(378, 'plPL', 'Nie pozwolę, by głupia ludzka biurokracja mieszała się do krasnoludzkich spraw, $N. Udowodniono, że Kam Głębogniew był spiskowcem w ataku na Most Thandol. Dobrzy poddani króla Magniego stracili życie przez podstęp Głębogniewa. Ludziom może wystarczać, że Głębogniew zgnije w Kazamatach, ale ja nie zaznam spokojnego snu, dopóki Głębogniew nie zginie.', 0);
